    """Return the run-length encoding of s, for example "aaabcc" -> "a3b1c2"."""
    if not s:
        return ""

    # Create a dictionary to count occurrences of each letter
    letter_counts = {}
    for char in s:
        if char in letter_counts:
            letter_counts[char] += 1
        else:
            letter_counts[char] = 1

    # Initialize the result string
    result = ""

    # Iterate over the dictionary to build the result string
    for char, count in letter_counts.items():
        # If it's the first occurrence or the count's first digit is 1, append the character
        if count == 1 or count == 10 and char.isupper() and char.lower() == char:
            result += char
        else:
            # If it's not the first occurrence or the count's first digit is 1, append the count and the character
            if count == 1:
                result += char
            else:
                result += str(count) + char

    return result
